-- Create profiles table
create table profiles (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users on delete cascade unique not null,
  email text not null,
  full_name text,
  phone text,
  role text not null check (role in ('consumer', 'supplier', 'pickup_point')),
  pickup_point_id uuid,
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now()
);

-- Enable RLS
alter table profiles enable row level security;

-- Create RLS policies
create policy "Users can view their own profile"
  on profiles for select
  using (auth.uid() = user_id);

create policy "Users can update their own profile"
  on profiles for update
  using (auth.uid() = user_id);

create policy "Users can insert their own profile"
  on profiles for insert
  with check (auth.uid() = user_id);

-- Create index for performance
create index profiles_user_id_idx on profiles(user_id);
create index profiles_role_idx on profiles(role);
create index profiles_pickup_point_id_idx on profiles(pickup_point_id);

-- Create supplier_lists table
create table supplier_lists (
  id uuid primary key default gen_random_uuid(),
  supplier_id uuid references auth.users on delete cascade not null,
  name text not null,
  min_discount decimal(5,2) not null check (min_discount >= 0 and min_discount <= 100),
  max_discount decimal(5,2) not null check (max_discount >= 0 and max_discount <= 100),
  min_reservation_value decimal(10,2) not null check (min_reservation_value > 0),
  max_reservation_value decimal(10,2) not null check (max_reservation_value > 0),
  status text default 'active' check (status in ('active', 'inactive', 'archived')),
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now(),
  constraint valid_discount_range check (max_discount >= min_discount),
  constraint valid_reservation_range check (max_reservation_value >= min_reservation_value)
);

-- Enable RLS
alter table supplier_lists enable row level security;

-- Create RLS policies
create policy "Anyone can view active supplier lists"
  on supplier_lists for select
  using (status = 'active');

create policy "Suppliers can view their own lists"
  on supplier_lists for select
  using (
    auth.uid() = supplier_id
  );

create policy "Suppliers can insert their own lists"
  on supplier_lists for insert
  with check (
    auth.uid() = supplier_id
  );

create policy "Suppliers can update their own lists"
  on supplier_lists for update
  using (
    auth.uid() = supplier_id
  );

-- Create index for performance
create index supplier_lists_supplier_id_idx on supplier_lists(supplier_id);
create index supplier_lists_status_idx on supplier_lists(status);

-- Create products table
create table products (
  id uuid primary key default gen_random_uuid(),
  supplier_list_id uuid references supplier_lists on delete cascade not null,
  supplier_id uuid references auth.users on delete cascade not null,
  name text not null,
  description text,
  image_url text not null,
  additional_images text[],
  original_price decimal(10,2) not null check (original_price > 0),
  available_sizes text[],
  available_colors text[],
  condition text check (condition in ('new', 'like_new', 'good', 'fair')),
  category text,
  stock integer default 1 check (stock >= 0),
  status text default 'active' check (status in ('active', 'inactive', 'sold_out')),
  created_at timestamp with time zone default now(),
  updated_at timestamp with time zone default now()
);

-- Enable RLS
alter table products enable row level security;

-- Create RLS policies
create policy "Anyone can view active products"
  on products for select
  using (status = 'active');

create policy "Suppliers can view their own products"
  on products for select
  using (
    auth.uid() = supplier_id
  );

create policy "Suppliers can insert their own products"
  on products for insert
  with check (
    auth.uid() = supplier_id
  );

create policy "Suppliers can update their own products"
  on products for update
  using (
    auth.uid() = supplier_id
  );

-- Create index for performance
create index products_supplier_list_id_idx on products(supplier_list_id);
create index products_supplier_id_idx on products(supplier_id);
create index products_status_idx on products(status);
create index products_category_idx on products(category);

