-- Function to check and create drops automatically when minimum value is reached
CREATE OR REPLACE FUNCTION check_and_create_drop()
RETURNS TRIGGER AS $$
DECLARE
  v_supplier_list_id UUID;
  v_pickup_point_id UUID;
  v_min_reservation_value NUMERIC;
  v_total_interest_value NUMERIC;
  v_existing_drop_id UUID;
  v_list_name TEXT;
  v_pickup_point_name TEXT;
  v_drop_name TEXT;
BEGIN
  -- Get the supplier list and pickup point from the new interest
  v_supplier_list_id := NEW.supplier_list_id;
  v_pickup_point_id := NEW.pickup_point_id;

  -- Get the minimum reservation value for this list
  SELECT min_reservation_value, name
  INTO v_min_reservation_value, v_list_name
  FROM supplier_lists
  WHERE id = v_supplier_list_id;

  -- Get pickup point name
  SELECT name INTO v_pickup_point_name
  FROM pickup_points
  WHERE id = v_pickup_point_id;

  -- Check if there's already a drop for this combination (pending_approval, approved, or active)
  SELECT id INTO v_existing_drop_id
  FROM drops
  WHERE supplier_list_id = v_supplier_list_id
    AND pickup_point_id = v_pickup_point_id
    AND status IN ('pending_approval', 'approved', 'active')
  LIMIT 1;

  -- If drop already exists, don't create a new one
  IF v_existing_drop_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Calculate total value of interested products for this list and pickup point
  SELECT COALESCE(SUM(p.original_price), 0)
  INTO v_total_interest_value
  FROM user_interests ui
  JOIN products p ON ui.product_id = p.id
  WHERE ui.supplier_list_id = v_supplier_list_id
    AND ui.pickup_point_id = v_pickup_point_id;

  -- If total interest value meets minimum, create a drop
  IF v_total_interest_value >= v_min_reservation_value THEN
    -- Create drop name
    v_drop_name := v_pickup_point_name || ' - ' || v_list_name;

    -- Create the drop
    INSERT INTO drops (
      supplier_list_id,
      pickup_point_id,
      name,
      current_discount,
      current_value,
      target_value,
      status,
      end_time
    )
    SELECT
      v_supplier_list_id,
      v_pickup_point_id,
      v_drop_name,
      sl.min_discount,
      0,
      sl.max_reservation_value,
      'pending_approval',
      NOW() + INTERVAL '5 days'
    FROM supplier_lists sl
    WHERE sl.id = v_supplier_list_id;

    RAISE NOTICE 'Drop created for % - % (value: %)', v_pickup_point_name, v_list_name, v_total_interest_value;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Create trigger on user_interests table
DROP TRIGGER IF EXISTS trigger_check_drop_creation ON user_interests;
CREATE TRIGGER trigger_check_drop_creation
  AFTER INSERT ON user_interests
  FOR EACH ROW
  EXECUTE FUNCTION check_and_create_drop();

-- Function to update drop discount based on booking value
CREATE OR REPLACE FUNCTION update_drop_discount()
RETURNS TRIGGER AS $$
DECLARE
  v_drop_id UUID;
  v_total_bookings_value NUMERIC;
  v_min_discount NUMERIC;
  v_max_discount NUMERIC;
  v_min_value NUMERIC;
  v_max_value NUMERIC;
  v_new_discount NUMERIC;
BEGIN
  -- Get the drop_id from the booking
  v_drop_id := NEW.drop_id;

  -- Get drop details
  SELECT 
    sl.min_discount,
    sl.max_discount,
    sl.min_reservation_value,
    sl.max_reservation_value
  INTO v_min_discount, v_max_discount, v_min_value, v_max_value
  FROM drops d
  JOIN supplier_lists sl ON d.supplier_list_id = sl.id
  WHERE d.id = v_drop_id;

  -- Calculate total bookings value for this drop
  SELECT COALESCE(SUM(original_price), 0)
  INTO v_total_bookings_value
  FROM bookings
  WHERE drop_id = v_drop_id
    AND payment_status IN ('authorized', 'captured')
    AND status = 'active';

  -- Calculate new discount percentage based on value progression
  -- Linear interpolation between min and max discount
  IF v_total_bookings_value <= v_min_value THEN
    v_new_discount := v_min_discount;
  ELSIF v_total_bookings_value >= v_max_value THEN
    v_new_discount := v_max_discount;
  ELSE
    v_new_discount := v_min_discount + 
      ((v_total_bookings_value - v_min_value) / (v_max_value - v_min_value)) * 
      (v_max_discount - v_min_discount);
  END IF;

  -- Update drop with new discount and current value
  UPDATE drops
  SET 
    current_discount = v_new_discount,
    current_value = v_total_bookings_value,
    updated_at = NOW()
  WHERE id = v_drop_id;

  RAISE NOTICE 'Drop % discount updated to % (value: %)', v_drop_id, v_new_discount, v_total_bookings_value;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Create trigger on bookings table
DROP TRIGGER IF EXISTS trigger_update_drop_discount ON bookings;
CREATE TRIGGER trigger_update_drop_discount
  AFTER INSERT OR UPDATE OF payment_status ON bookings
  FOR EACH ROW
  WHEN (NEW.payment_status IN ('authorized', 'captured') AND NEW.status = 'active')
  EXECUTE FUNCTION update_drop_discount();

