const handlePrenotaConCarta = async () => {
  try {
    // 1. Verify user has a payment method
    if (!paymentMethods || paymentMethods.length === 0) {
      Alert.alert(
        'No Payment Method',
        'Please add a payment method before booking.'
      );
      router.push('/add-payment-method');
      return;
