    // 2. Calculate the initial amount to block based on the current discount
    const discountedPrice = product.original_price * (1 - (currentDrop.current_discount / 100));
    const amountToBlock = discountedPrice;

    // 3. Create a booking in the database with status 'authorized'
    const { data: bookingData, error: bookingError } = await supabase
      .from('bookings')
      .insert([
        {
          user_id: user.id,
          product_id: product.id,
          drop_id: dropId,
          status: 'authorized',
          amount_authorized: amountToBlock,
        },
      ])
      .select()
      .single();

    if (bookingError) {
      console.error('Error creating booking:', bookingError);
      Alert.alert('Error', 'Failed to create booking. Please try again.');
      return;
    }

    // 4. Call the payment provider to authorize the amount
    const paymentResult = await authorizePayment(amountToBlock, paymentMethods[0].id); // Assuming the first payment method is used

    if (!paymentResult.success) {
      console.error('Payment authorization failed:', paymentResult.error);
      Alert.alert('Error', 'Payment authorization failed. Please try again.');

      // Optionally, revert the booking status in the database
      await supabase
        .from('bookings')
        .update({ status: 'failed' })
        .eq('id', bookingData.id);

      return;
    }

    // 5. Update the current value of the drop
