-- Create a function to broadcast drop updates via Supabase Realtime
CREATE OR REPLACE FUNCTION broadcast_drop_update()
RETURNS TRIGGER AS $$
DECLARE
  drop_data jsonb;
BEGIN
  -- Build the drop data payload
  SELECT jsonb_build_object(
    'id', NEW.id,
    'name', NEW.name,
    'current_discount', NEW.current_discount,
    'current_value', NEW.current_value,
    'target_value', NEW.target_value,
    'status', NEW.status,
    'start_time', NEW.start_time,
    'end_time', NEW.end_time,
    'updated_at', NEW.updated_at
  ) INTO drop_data;

  -- Broadcast to the drop-specific channel
  PERFORM pg_notify(
    'drop_update_' || NEW.id::text,
    drop_data::text
  );

  -- Also broadcast to the general drops channel for the pickup point
  PERFORM pg_notify(
    'drops_' || NEW.pickup_point_id::text,
    drop_data::text
  );

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Create trigger for drop updates
DROP TRIGGER IF EXISTS trigger_broadcast_drop_update ON drops;
CREATE TRIGGER trigger_broadcast_drop_update
  AFTER UPDATE OF current_discount, current_value, status
  ON drops
  FOR EACH ROW
  EXECUTE FUNCTION broadcast_drop_update();

-- Create a function to broadcast booking updates
CREATE OR REPLACE FUNCTION broadcast_booking_update()
RETURNS TRIGGER AS $$
DECLARE
  booking_data jsonb;
BEGIN
  -- Build the booking data payload
  SELECT jsonb_build_object(
    'id', NEW.id,
    'drop_id', NEW.drop_id,
    'product_id', NEW.product_id,
    'user_id', NEW.user_id,
    'payment_status', NEW.payment_status,
    'status', NEW.status,
    'created_at', NEW.created_at
  ) INTO booking_data;

  -- Broadcast to the drop-specific bookings channel
  PERFORM pg_notify(
    'bookings_' || NEW.drop_id::text,
    booking_data::text
  );

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Create trigger for booking updates
DROP TRIGGER IF EXISTS trigger_broadcast_booking_update ON bookings;
CREATE TRIGGER trigger_broadcast_booking_update
  AFTER INSERT OR UPDATE
  ON bookings
  FOR EACH ROW
  EXECUTE FUNCTION broadcast_booking_update();

