import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from 'jsr:@supabase/supabase-js@2';

const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;

interface UnderfundedDropNotification {
  dropId: string;
  dropName: string;
  currentValue: number;
  minValue: number;
  pickupPointName: string;
}

Deno.serve(async (req: Request) => {
  try {
    // Only allow POST requests
    if (req.method !== 'POST') {
      return new Response(
        JSON.stringify({ error: 'Method not allowed' }),
        { status: 405, headers: { 'Content-Type': 'application/json' } }
      );
    }

    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    // Get the drop ID from the request body
    const { dropId } = await req.json();

    if (!dropId) {
      return new Response(
        JSON.stringify({ error: 'Drop ID is required' }),
        { status: 400, headers: { 'Content-Type': 'application/json' } }
      );
    }

    console.log('Processing underfunded drop:', dropId);

    // Get drop details
    const { data: drop, error: dropError } = await supabase
      .from('drops')
      .select(`
        id,
        name,
        current_value,
        status,
        pickup_points (
          name,
          city
        ),
        supplier_lists (
          name,
          min_reservation_value
        )
      `)
      .eq('id', dropId)
      .single();

    if (dropError || !drop) {
      console.error('Error fetching drop:', dropError);
      return new Response(
        JSON.stringify({ error: 'Drop not found' }),
        { status: 404, headers: { 'Content-Type': 'application/json' } }
      );
    }

    // Verify the drop is actually underfunded
    if (drop.status !== 'underfunded') {
      return new Response(
        JSON.stringify({ error: 'Drop is not underfunded' }),
        { status: 400, headers: { 'Content-Type': 'application/json' } }
      );
    }

    console.log('Drop is underfunded, releasing funds...');

    // Call the function to release funds and get affected users
    const { data: refundedBookings, error: refundError } = await supabase
      .rpc('release_underfunded_drop_funds', { drop_id_param: dropId });

    if (refundError) {
      console.error('Error releasing funds:', refundError);
      return new Response(
        JSON.stringify({ error: 'Failed to release funds' }),
        { status: 500, headers: { 'Content-Type': 'application/json' } }
      );
    }

    console.log(`Released funds for ${refundedBookings?.length || 0} bookings`);

    // TODO: Send notifications to users
    // In a production environment, you would:
    // 1. Send push notifications via Expo Push Notifications
    // 2. Send emails via SendGrid, AWS SES, or similar
    // 3. Create in-app notifications

    const notificationMessage = `Il drop "${drop.name}" non ha raggiunto l'ordine minimo di €${drop.supplier_lists.min_reservation_value}. ` +
      `Abbiamo raccolto solo €${drop.current_value}. ` +
      `L'importo bloccato sulla tua carta è stato rilasciato. ` +
      `Condividi il prossimo drop con amici e parenti per raggiungere l'obiettivo!`;

    console.log('Notification message:', notificationMessage);
    console.log('Users to notify:', refundedBookings?.map((b: any) => b.user_email));

    // Mark the drop as notified
    const { error: updateError } = await supabase
      .from('drops')
      .update({ underfunded_notified_at: new Date().toISOString() })
      .eq('id', dropId);

    if (updateError) {
      console.error('Error updating notification timestamp:', updateError);
    }

    return new Response(
      JSON.stringify({
        success: true,
        message: 'Funds released and users notified',
        refundedBookings: refundedBookings?.length || 0,
        notificationMessage,
      }),
      {
        status: 200,
        headers: {
          'Content-Type': 'application/json',
          'Connection': 'keep-alive',
        },
      }
    );
  } catch (error) {
    console.error('Error in handle-underfunded-drops:', error);
    return new Response(
      JSON.stringify({ error: 'Internal server error', details: error.message }),
      { status: 500, headers: { 'Content-Type': 'application/json' } }
    );
  }
});

