-- Fix the check_and_create_drop function to set current_value to 0 initially
-- The current_value should only reflect actual card bookings, not user interests

CREATE OR REPLACE FUNCTION check_and_create_drop()
RETURNS TRIGGER AS $$
DECLARE
  v_supplier_list_id uuid;
  v_pickup_point_id uuid;
  v_total_interest_value numeric;
  v_min_value numeric;
  v_existing_drop_id uuid;
  v_drop_name text;
  v_min_discount numeric;
  v_max_discount numeric;
  v_max_value numeric;
BEGIN
  v_supplier_list_id := NEW.supplier_list_id;
  v_pickup_point_id := NEW.pickup_point_id;

  -- Get supplier list settings
  SELECT min_reservation_value, min_discount, max_discount, max_reservation_value
  INTO v_min_value, v_min_discount, v_max_discount, v_max_value
  FROM supplier_lists
  WHERE id = v_supplier_list_id;

  -- Calculate total interest value (for drop creation threshold only)
  SELECT COALESCE(SUM(p.original_price), 0)
  INTO v_total_interest_value
  FROM user_interests ui
  JOIN products p ON ui.product_id = p.id
  WHERE ui.supplier_list_id = v_supplier_list_id
    AND ui.pickup_point_id = v_pickup_point_id;

  -- Create drop if interest threshold is met
  IF v_total_interest_value >= v_min_value THEN
    -- Check if drop already exists
    SELECT id INTO v_existing_drop_id
    FROM drops
    WHERE supplier_list_id = v_supplier_list_id
      AND pickup_point_id = v_pickup_point_id
      AND status IN ('pending_approval', 'approved', 'active')
    LIMIT 1;

    -- Create new drop if none exists
    IF v_existing_drop_id IS NULL THEN
      SELECT pp.city || ' - ' || sl.name
      INTO v_drop_name
      FROM pickup_points pp, supplier_lists sl
      WHERE pp.id = v_pickup_point_id
        AND sl.id = v_supplier_list_id;

      INSERT INTO drops (
        supplier_list_id,
        pickup_point_id,
        name,
        current_discount,
        current_value,  -- Set to 0, will be updated by bookings
        target_value,
        status,
        start_time,
        end_time
      ) VALUES (
        v_supplier_list_id,
        v_pickup_point_id,
        v_drop_name,
        v_min_discount,
        0,  -- Start at 0, only card bookings count
        v_max_value,
        'pending_approval',
        NOW(),
        NOW() + INTERVAL '5 days'
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Update existing active drops to have correct current_value based on bookings only
UPDATE drops
SET current_value = COALESCE((
  SELECT SUM(authorized_amount)
  FROM bookings
  WHERE bookings.drop_id = drops.id
    AND bookings.payment_status = 'authorized'
    AND bookings.status = 'active'
), 0),
updated_at = NOW()
WHERE status IN ('active', 'approved', 'pending_approval');

