AS $$
DECLARE
  v_supplier_list_id UUID;
  v_pickup_point_id UUID;
  v_min_reservation_value NUMERIC;
  v_max_reservation_value NUMERIC;
  v_min_discount NUMERIC;
  v_max_discount NUMERIC;
  v_total_interest_value NUMERIC;
  v_existing_drop_id UUID;
BEGIN
  -- Get the supplier list and pickup point for this interest
  SELECT 
    ui.supplier_list_id,
    ui.pickup_point_id
  INTO 
    v_supplier_list_id,
    v_pickup_point_id
  FROM user_interests ui
  WHERE ui.id = NEW.id;

  -- Get supplier list details
  SELECT 
    min_reservation_value,
    max_reservation_value,
    min_discount,
    max_discount
  INTO 
    v_min_reservation_value,
    v_max_reservation_value,
    v_min_discount,
    v_max_discount
  FROM supplier_lists
  WHERE id = v_supplier_list_id;

  -- Check if there's already an active or pending drop for this combination
  SELECT id INTO v_existing_drop_id
  FROM drops
  WHERE supplier_list_id = v_supplier_list_id
    AND pickup_point_id = v_pickup_point_id
    AND status IN ('pending_approval', 'approved', 'active')
  LIMIT 1;

  -- If drop already exists, skip
  IF v_existing_drop_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Calculate total interest value for this supplier list and pickup point
  SELECT COALESCE(SUM(p.original_price), 0)
  INTO v_total_interest_value
  FROM user_interests ui
  JOIN products p ON p.id = ui.product_id
  WHERE ui.supplier_list_id = v_supplier_list_id
    AND ui.pickup_point_id = v_pickup_point_id;

  -- If minimum threshold is met, create a drop
  IF v_total_interest_value >= v_min_reservation_value THEN
    INSERT INTO drops (
      supplier_list_id,
      pickup_point_id,
      name,
      current_discount,
      current_value,
      target_value,
      status,
      start_time,
      end_time
    ) VALUES (
      v_supplier_list_id,
      v_pickup_point_id,
      (SELECT name FROM pickup_points WHERE id = v_pickup_point_id) || ' - ' || 
      (SELECT name FROM supplier_lists WHERE id = v_supplier_list_id),
      v_min_discount,
      0,
      v_max_reservation_value,
      'pending_approval',
      NOW(),
      NOW() + INTERVAL '5 days'
    );
  END IF;

  RETURN NEW;
END;
$$;

-- =====================================================
-- PART 4: ADD MISSING INDEXES FOR FOREIGN KEYS
-- =====================================================

-- Add indexes for foreign keys that don't have covering indexes
CREATE INDEX IF NOT EXISTS idx_drops_approved_by ON drops(approved_by);
CREATE INDEX IF NOT EXISTS idx_drops_deactivated_by ON drops(deactivated_by);

-- =====================================================
-- PART 5: CREATE HELPER FUNCTION FOR ADMIN CHECK
-- (if it doesn't exist already)
-- =====================================================

CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
STABLE
AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM profiles
    WHERE user_id = auth.uid()
      AND role = 'admin'
  );
END;
$$;

-- Add comment explaining the migration
COMMENT ON FUNCTION public.is_admin() IS 'Helper function to check if current user is admin. Uses STABLE and secure search_path for performance and security.';
COMMENT ON FUNCTION public.check_underfunded_drops() IS 'Checks for underfunded drops and marks them. Uses secure search_path.';
COMMENT ON FUNCTION public.release_underfunded_drop_funds() IS 'Releases funds for underfunded drops. Uses secure search_path.';
COMMENT ON FUNCTION public.check_and_create_drop() IS 'Trigger function to automatically create drops when interest threshold is met. Uses secure search_path.';

