import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
      {
        auth: {
          autoRefreshToken: false,
          persistSession: false,
        },
      }
    );

    // Verify the request is from an admin
    const authHeader = req.headers.get('Authorization');
    const token = authHeader.replace('Bearer ', '');
    const { data: { user }, error: userError } = await supabaseAdmin.auth.getUser(token);

    if (userError || !user) {
      return new Response(
        JSON.stringify({ error: 'Unauthorized' }),
        {
          status: 401,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        }
      );
    }

    // Check if user is admin
    const { data: profile } = await supabaseAdmin
      .from('profiles')
      .select('role')
      .eq('user_id', user.id)
      .single();

    if (!profile || profile.role !== 'admin') {
      return new Response(
        JSON.stringify({ error: 'Forbidden: Admin access required' }),
        {
          status: 403,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        }
      );
    }

    // Get request body
    const { email, password, fullName, phone, pointName, address, city, postalCode, commissionRate } = await req.json();

    // Validate required fields
    if (!email || !password || !fullName || !phone || !pointName || !address || !city) {
      return new Response(
        JSON.stringify({ error: 'Missing required fields' }),
        {
          status: 400,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        }
      );
    }

    console.log('Creating pickup point user:', email);

    // First, create the pickup point
    const { data: pickupPointData, error: pickupPointError } = await supabaseAdmin
      .from('pickup_points')
      .insert({
        name: pointName,
        address,
        city,
        postal_code: postalCode || null,
        phone,
        email: email.toLowerCase(),
        manager_name: fullName,
        commission_rate: commissionRate || 5.00,
        status: 'active',
      })
      .select()
      .single();

    if (pickupPointError) {
      console.error('Error creating pickup point:', pickupPointError);
      return new Response(
        JSON.stringify({ error: pickupPointError.message }),
        {
          status: 400,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        }
      );
    }

    console.log('Pickup point created:', pickupPointData.id);

    // Now create the user account with the pickup_point_id in metadata
    const { data: authData, error: authError } = await supabaseAdmin.auth.admin.createUser({
      email: email.toLowerCase(),
      password,
      email_confirm: true,
      user_metadata: {
        full_name: fullName,
        phone,
        role: 'pickup_point',
        pickup_point_id: pickupPointData.id,
      },
    });

    if (authError) {
      console.error('Error creating user:', authError);
      // Rollback: delete the pickup point
      await supabaseAdmin.from('pickup_points').delete().eq('id', pickupPointData.id);
      return new Response(
        JSON.stringify({ error: authError.message }),
        {
          status: 400,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        }
      );
    }

    if (!authData.user) {
      // Rollback: delete the pickup point
      await supabaseAdmin.from('pickup_points').delete().eq('id', pickupPointData.id);
      return new Response(
        JSON.stringify({ error: 'Failed to create user' }),
        {
          status: 500,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        }
      );
    }

    console.log('User created:', authData.user.id);

    // Wait a moment for the trigger to create the profile
    await new Promise(resolve => setTimeout(resolve, 500));

    // Verify the profile was created with the correct pickup_point_id
    const { data: profileData, error: profileCheckError } = await supabaseAdmin
      .from('profiles')
      .select('*')
      .eq('user_id', authData.user.id)
      .single();

    if (profileCheckError || !profileData) {
      console.error('Profile not found after creation, creating manually:', profileCheckError);

      // Create the profile manually if the trigger failed
      const { error: profileInsertError } = await supabaseAdmin
        .from('profiles')
        .insert({
          user_id: authData.user.id,
          email: email.toLowerCase(),
          full_name: fullName,
          phone,
          role: 'pickup_point',
          pickup_point_id: pickupPointData.id,
        });

      if (profileInsertError) {
        console.error('Error creating profile manually:', profileInsertError);
        // Don't fail the entire operation, but log the error
      }
    } else if (!profileData.pickup_point_id) {
      console.error('Profile created but pickup_point_id is null, updating...');

      // Update the profile to set the pickup_point_id
      const { error: profileUpdateError } = await supabaseAdmin
        .from('profiles')
        .update({ pickup_point_id: pickupPointData.id })
        .eq('user_id', authData.user.id);

      if (profileUpdateError) {
        console.error('Error updating profile with pickup_point_id:', profileUpdateError);
      }
    } else {
      console.log('Profile created successfully with pickup_point_id:', profileData.pickup_point_id);
    }

    return new Response(
      JSON.stringify({
        success: true,
        pickupPoint: pickupPointData,
      }),
      {
        status: 200,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      }
    );
  } catch (error) {
    console.error('Exception:', error);
    return new Response(
      JSON.stringify({ error: error.message }),
      {
        status: 500,
        headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      }
    );
  }
});

