-- Migration to fix and prevent pickup point users without pickup_point_id

-- 1. Create a function to automatically link pickup point users to their pickup points
CREATE OR REPLACE FUNCTION auto_link_pickup_point_user()
RETURNS TRIGGER AS $$
DECLARE
  v_pickup_point_id uuid;
BEGIN
  -- Only process pickup_point role users
  IF NEW.role = 'pickup_point' AND NEW.pickup_point_id IS NULL THEN
    -- Try to find the pickup point by email
    SELECT id INTO v_pickup_point_id
    FROM pickup_points
    WHERE email = NEW.email
    LIMIT 1;

    IF v_pickup_point_id IS NOT NULL THEN
      -- Update the pickup_point_id
      NEW.pickup_point_id := v_pickup_point_id;
      RAISE LOG 'Auto-linked pickup point user % to pickup point %', NEW.email, v_pickup_point_id;
    ELSE
      RAISE WARNING 'Pickup point user % created without pickup_point_id and no matching pickup point found', NEW.email;
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 2. Create a trigger to run the function before insert or update
DROP TRIGGER IF EXISTS auto_link_pickup_point_user_trigger ON profiles;
CREATE TRIGGER auto_link_pickup_point_user_trigger
  BEFORE INSERT OR UPDATE ON profiles
  FOR EACH ROW
  EXECUTE FUNCTION auto_link_pickup_point_user();

-- 3. Fix any existing pickup point users that are missing pickup_point_id
UPDATE profiles p
SET pickup_point_id = pp.id
FROM pickup_points pp
WHERE p.role = 'pickup_point'
  AND p.pickup_point_id IS NULL
  AND p.email = pp.email;

-- 4. Log the results
DO $$
DECLARE
  v_fixed_count integer;
  v_remaining_count integer;
BEGIN
  -- Count how many were fixed
  SELECT COUNT(*) INTO v_fixed_count
  FROM profiles p
  INNER JOIN pickup_points pp ON p.email = pp.email
  WHERE p.role = 'pickup_point' AND p.pickup_point_id = pp.id;

  -- Count how many still need fixing
  SELECT COUNT(*) INTO v_remaining_count
  FROM profiles
  WHERE role = 'pickup_point' AND pickup_point_id IS NULL;

  RAISE NOTICE 'Fixed % pickup point users', v_fixed_count;

  IF v_remaining_count > 0 THEN
    RAISE WARNING '% pickup point users still missing pickup_point_id', v_remaining_count;
  END IF;
END $$;

-- 5. Create an index to improve performance of the email lookup
CREATE INDEX IF NOT EXISTS idx_pickup_points_email ON pickup_points(email);
CREATE INDEX IF NOT EXISTS idx_profiles_role_pickup_point_id ON profiles(role, pickup_point_id) WHERE role = 'pickup_point';

COMMENT ON FUNCTION auto_link_pickup_point_user() IS 'Automatically links pickup point users to their pickup points by matching email addresses';
COMMENT ON TRIGGER auto_link_pickup_point_user_trigger ON profiles IS 'Ensures pickup point users are always linked to their pickup points';

