      (SELECT name FROM pickup_points WHERE id = v_pickup_point_id) || ' - ' || 
      (SELECT name FROM supplier_lists WHERE id = v_supplier_list_id),
      v_min_discount,
      0,
      v_max_reservation_value,
      'pending_approval',
      NOW(),
      NOW() + INTERVAL '5 days'
    );
  END IF;

  RETURN NEW;
END;
"},{"routine_name":"check_underfunded_drops","routine_definition":"
BEGIN
  UPDATE drops
  SET 
    status = 'underfunded',
    underfunded_notified_at = NOW()
  WHERE 
    status = 'active'
