"},{"routine_name":"handle_drop_completion","routine_definition":"
DECLARE
  v_order_number text;
  v_order_id uuid;
  v_supplier_id uuid;
  v_total_value numeric;
  v_commission_rate numeric;
  v_commission_amount numeric;
BEGIN
  IF NEW.status = 'completed' AND OLD.status != 'completed' THEN
    SELECT sl.supplier_id
    INTO v_supplier_id
    FROM supplier_lists sl
    WHERE sl.id = NEW.supplier_list_id;

    SELECT COALESCE(SUM(final_price), 0)
    INTO v_total_value
    FROM bookings
    WHERE drop_id = NEW.id
      AND payment_status = 'captured'
      AND status = 'confirmed';

    SELECT commission_rate
    INTO v_commission_rate
    FROM pickup_points
    WHERE id = NEW.pickup_point_id;

    v_commission_amount := v_total_value * (v_commission_rate / 100);

    v_order_number := 'ORD-' || TO_CHAR(NOW(), 'YYYYMMDD') || '-' || 
                      LPAD(NEXTVAL('order_number_seq')::text, 6, '0');

    INSERT INTO orders (
      order_number,
      drop_id,
      supplier_id,
      pickup_point_id,
      total_value,
      commission_amount,
      status
    ) VALUES (
      v_order_number,
      NEW.id,
      v_supplier_id,
      NEW.pickup_point_id,
      v_total_value,
      v_commission_amount,
      'pending'
    )
    RETURNING id INTO v_order_id;

    INSERT INTO order_items (
      order_id,
      booking_id,
      product_id,
      user_id,
      product_name,
      selected_size,
      selected_color,
      original_price,
      discount_percentage,
      final_price,
      pickup_status
    )
    SELECT
      v_order_id,
      b.id,
      b.product_id,
      b.user_id,
      p.name,
      b.selected_size,
      b.selected_color,
      b.original_price,
      b.discount_percentage,
      b.final_price,
      'pending'
    FROM bookings b
    JOIN products p ON b.product_id = p.id
    WHERE b.drop_id = NEW.id
      AND b.payment_status = 'captured'
      AND b.status = 'confirmed';

    UPDATE bookings
    SET status = 'completed'
    WHERE drop_id = NEW.id
      AND payment_status = 'captured'
      AND status = 'confirmed';
  END IF;

  RETURN NEW;
END;
"},{"routine_name":"handle_new_user","routine_definition":"
DECLARE
  v_pickup_point_id uuid;
  v_error_message text;
BEGIN
  -- Log the start of profile creation
  RAISE LOG 'Starting profile creation for user %', new.id;

  -- Convert pickup_point_id from text to uuid, handling null values
  BEGIN
    v_pickup_point_id := (new.raw_user_meta_data->>'pickup_point_id')::uuid;
  EXCEPTION WHEN others THEN
    v_pickup_point_id := null;
    RAISE LOG 'Could not parse pickup_point_id for user %: %', new.id, SQLERRM;
  END;

  -- Insert profile with data from user metadata
  BEGIN
    INSERT INTO public.profiles (user_id, email, full_name, phone, role, pickup_point_id)
    VALUES (
      new.id,
      new.email,
      COALESCE(new.raw_user_meta_data->>'full_name', ''),
      new.raw_user_meta_data->>'phone',
      COALESCE(new.raw_user_meta_data->>'role', 'consumer'),
      v_pickup_point_id
    );

    RAISE LOG 'Successfully created profile for user %', new.id;

  EXCEPTION WHEN foreign_key_violation THEN
    -- This should not happen, but log it if it does
    v_error_message := SQLERRM;
    RAISE WARNING 'Foreign key violation creating profile for user %: %. This may indicate a timing issue.', new.id, v_error_message;

    -- Don't fail the user creation, but log the error
    RETURN new;

  WHEN unique_violation THEN
    -- Profile already exists, this is OK
    RAISE LOG 'Profile already exists for user %, skipping creation', new.id;
    RETURN new;

  WHEN others THEN
    -- Log any other error but don't fail the user creation
    v_error_message := SQLERRM;
    RAISE WARNING 'Error creating profile for user %: %', new.id, v_error_message;
    RETURN new;
  END;

  RETURN new;
END;
"},{"routine_name":"is_admin","routine_definition":"
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM profiles
    WHERE user_id = auth.uid()
      AND role = 'admin'
  );
END;
"},{"routine_name":"release_underfunded_drop_funds","routine_definition":"
