```tsx
import React from 'react';
import { View, Text, Button, StyleSheet, Alert } from 'react-native';
import * as FileSystem from 'expo-file-system';
import * as Sharing from 'expo-sharing';

const ProfileScreen = () => {

  const handleExportData = async () => {
    try {
      // Simulate fetching user data (replace with actual data fetching logic)
      const userData = {
        name: 'John Doe',
        email: 'john.doe@example.com',
        orders: [
          { id: 1, product: 'Product A', price: 20 },
          { id: 2, product: 'Product B', price: 30 },
        ],
      };

      // Convert user data to JSON string
      const jsonString = JSON.stringify(userData, null, 2);

      // Define file path
      const fileName = 'user_data.json';
      const fileUri = FileSystem.documentDirectory + fileName;

      // Write JSON string to file
      await FileSystem.writeAsStringAsync(fileUri, jsonString, {
        encoding: FileSystem.EncodingType.UTF8,
      });

      // Share the file
      await Sharing.shareAsync(fileUri, {
        mimeType: 'application/json',
        dialogTitle: 'Export User Data',
        UTI: 'com.json',
      });

    } catch (error: any) {
      console.error('Error exporting data:', error);
      Alert.alert('Error', 'Failed to export data. Please try again.');
    }
  };

  return (
    <View style={styles.container}>
      <Text>Profile Screen</Text>
      <Button title="Esporta i tuoi dati" onPress={handleExportData} />
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
});

export default ProfileScreen;
```

**Explanation of Changes:**

1.  **Import necessary modules:**
    *   `expo-file-system` for file system operations.
    *   `expo-sharing` for sharing the generated file.
2.  **`handleExportData` function:**
    *   Simulates fetching user data (replace with your actual data fetching logic).
    *   Converts the data to a JSON string using `JSON.stringify`.
    *   Defines the file name and path using `FileSystem.documentDirectory`.
    *   Writes the JSON string to the file using `FileSystem.writeAsStringAsync`.
    *   Shares the file using `Sharing.shareAsync`.
    *   Includes error handling with `Alert.alert` to display error messages to the user.
3.  **Button `onPress` handler:**
    *   The "Esporta i tuoi dati" button now calls the `handleExportData` function when pressed.

**To complete this implementation:**

1.  Replace the simulated user data with your actual data fetching logic.
2.  Ensure that `expo-file-system` and `expo-sharing` are installed in your project:

```bash
npx expo install expo-file-system expo-sharing
```

