// app/add-payment-method.native.tsx
import { createPaymentMethod } from '@stripe/stripe-react-native';
import { supabase } from '../integrations/supabase/client';

async function addPaymentMethod(cardDetails: any, userId: string) {
  try {
    const { paymentMethod, error } = await createPaymentMethod({
      type: 'Card',
      card: cardDetails,
    });

    if (error) {
      throw new Error(error.message);
    }

    const { card } = paymentMethod;
    const card_last4 = card?.last4;
    const card_brand = card?.brand;
    const card_exp_month = card?.exp_month;
    const card_exp_year = card?.exp_year;
    const stripe_payment_method_id = paymentMethod.id;

    const { data, error: dbError } = await supabase
      .from('payment_methods')
      .insert({
        user_id: userId,
        stripe_payment_method_id,
        card_last4,
        card_brand,
        card_exp_month,
        card_exp_year,
        is_default: true,
        status: 'active',
      });

    if (dbError) {
      throw new Error(dbError.message);
    }

    return data;
  } catch (e: any) {
    console.error("Error adding payment method:", e.message);
    throw e;
  }
}
