    OR
    -- Fire for card bookings with authorized/captured status
    (NEW.payment_method = 'card' AND NEW.payment_status IN ('authorized', 'captured') AND NEW.status = 'active')
  )
  EXECUTE FUNCTION update_drop_discount();

