-- Migration: Add automatic stock management triggers
-- This ensures stock is properly managed when bookings are created or cancelled

-- Function to manage stock when bookings are created
CREATE OR REPLACE FUNCTION manage_product_stock_on_booking()
RETURNS TRIGGER AS $$
DECLARE
  v_current_stock INTEGER;
BEGIN
  -- Handle INSERT (new booking)
  IF (TG_OP = 'INSERT') THEN
    -- Lock the product row and get current stock
    SELECT stock INTO v_current_stock
    FROM products
    WHERE id = NEW.product_id
    FOR UPDATE;

    -- Check if product exists
    IF v_current_stock IS NULL THEN
      RAISE EXCEPTION 'Product not found: %', NEW.product_id;
    END IF;

    -- Check if stock is available
    IF v_current_stock <= 0 THEN
      RAISE EXCEPTION 'Product out of stock. Current stock: %', v_current_stock;
    END IF;

    -- Decrement stock
    UPDATE products
    SET 
      stock = stock - 1,
      updated_at = NOW()
    WHERE id = NEW.product_id;

    RAISE LOG 'Stock decremented for product %: % -> %', NEW.product_id, v_current_stock, v_current_stock - 1;

    RETURN NEW;
  END IF;

  -- Handle UPDATE (booking status change)
  IF (TG_OP = 'UPDATE') THEN
    -- If booking is being cancelled, restore stock
    IF (OLD.status IN ('active', 'confirmed') AND NEW.status = 'cancelled') THEN
      UPDATE products
      SET 
        stock = stock + 1,
        updated_at = NOW()
      WHERE id = NEW.product_id;

      RAISE LOG 'Stock restored for product % due to booking cancellation', NEW.product_id;
    END IF;

    RETURN NEW;
  END IF;

  -- Handle DELETE (booking deletion - restore stock)
  IF (TG_OP = 'DELETE') THEN
    -- Only restore stock if the booking was active or confirmed
    IF (OLD.status IN ('active', 'confirmed')) THEN
      UPDATE products
      SET 
        stock = stock + 1,
        updated_at = NOW()
      WHERE id = OLD.product_id;

      RAISE LOG 'Stock restored for product % due to booking deletion', OLD.product_id;
    END IF;

    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- Drop existing trigger if it exists
DROP TRIGGER IF EXISTS trigger_manage_stock_on_booking ON bookings;

-- Create trigger for stock management
CREATE TRIGGER trigger_manage_stock_on_booking
  BEFORE INSERT OR UPDATE OR DELETE ON bookings
  FOR EACH ROW
  EXECUTE FUNCTION manage_product_stock_on_booking();

