    WHERE id = NEW.product_id;

    RAISE LOG 'Stock decremented for product % (%): % -> %', NEW.product_id, v_product_name, v_current_stock, v_current_stock - 1;

    RETURN NEW;
  END IF;

  -- Handle UPDATE (booking status change)
  IF (TG_OP = 'UPDATE') THEN
    -- If booking is being cancelled, restore stock
    IF (OLD.status IN ('active', 'confirmed') AND NEW.status = 'cancelled') THEN
      UPDATE products
      SET 
        stock = stock + 1,
        updated_at = NOW()
      WHERE id = NEW.product_id;

      RAISE LOG 'Stock restored for product % due to booking cancellation', NEW.product_id;
    END IF;

    RETURN NEW;
  END IF;

  -- Handle DELETE (booking deletion - restore stock)
  IF (TG_OP = 'DELETE') THEN
    -- Only restore stock if the booking was active or confirmed
    IF (OLD.status IN ('active', 'confirmed')) THEN
      UPDATE products
      SET 
        stock = stock + 1,
        updated_at = NOW()
      WHERE id = OLD.product_id;

      RAISE LOG 'Stock restored for product % due to booking deletion', OLD.product_id;
    END IF;

    RETURN OLD;
  END IF;

  RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- ============================================================================
-- ADD CONSTRAINT TO ENSURE STOCK IS NEVER NULL
-- ============================================================================

-- Set default value for stock if not already set
ALTER TABLE products 
ALTER COLUMN stock SET DEFAULT 1;

-- Update any existing NULL stock values to 1
UPDATE products 
SET stock = 1 
WHERE stock IS NULL;

-- Add NOT NULL constraint
ALTER TABLE products 
ALTER COLUMN stock SET NOT NULL;

-- Add check constraint to ensure stock is never negative
ALTER TABLE products 
DROP CONSTRAINT IF EXISTS products_stock_check;

ALTER TABLE products 
ADD CONSTRAINT products_stock_check CHECK (stock >= 0);

-- ============================================================================
