-- ============================================================================

COMMENT ON FUNCTION manage_product_stock_on_booking() IS 
  'Manages product stock when bookings are created, updated, or deleted. Provides user-friendly error messages.';

COMMENT ON CONSTRAINT products_stock_check ON products IS 
  'Ensures stock is never negative';

