      AND payment_status IN ('authorized', 'pending')
      AND status = 'active';

    -- Calculate discount
    v_min_discount := v_drop.min_discount;
    v_max_discount := v_drop.max_discount;
    v_min_value := v_drop.min_reservation_value;
    v_max_value := v_drop.max_reservation_value;

    IF v_current_value <= v_min_value THEN
      v_new_discount := v_min_discount;
    ELSIF v_current_value >= v_max_value THEN
      v_new_discount := v_max_discount;
    ELSE
      v_new_discount := v_min_discount + 
        ((v_max_discount - v_min_discount) * 
         ((v_current_value - v_min_value) / (v_max_value - v_min_value)));
    END IF;

    -- Update the drop
    UPDATE drops
    SET current_discount = v_new_discount,
        current_value = v_current_value,
        updated_at = NOW()
    WHERE id = v_drop.id;

    RAISE NOTICE 'Recalculated drop %: value=% discount=%', v_drop.id, v_current_value, v_new_discount;
  END LOOP;

  RAISE NOTICE 'Recalculation complete!';
END $$;

-- ============================================================================
-- Add index to improve performance of drop value calculations
-- ============================================================================
CREATE INDEX IF NOT EXISTS idx_bookings_drop_status_payment 
ON bookings(drop_id, status, payment_status) 
WHERE status = 'active' AND payment_status IN ('authorized', 'pending');

-- ============================================================================
-- Grant necessary permissions
-- ============================================================================
GRANT EXECUTE ON FUNCTION update_drop_discount() TO authenticated;
GRANT EXECUTE ON FUNCTION broadcast_drop_update() TO authenticated;
GRANT EXECUTE ON FUNCTION notify_product_stock_change() TO authenticated;

