-- Remove redundant triggers that might conflict with update_drop_discount
-- The update_drop_discount trigger is the correct one (uses final_price)
-- The update_drop_on_booking triggers are redundant (use original_price)

DROP TRIGGER IF EXISTS trigger_update_drop_on_booking_insert ON bookings;
DROP TRIGGER IF EXISTS trigger_update_drop_on_booking_update ON bookings;
DROP TRIGGER IF EXISTS trigger_update_drop_on_booking_delete ON bookings;

-- Drop the redundant function
DROP FUNCTION IF EXISTS update_drop_on_booking();

-- Verify we still have the correct triggers
DO $$
DECLARE
  v_trigger_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_trigger_count
  FROM information_schema.triggers
  WHERE trigger_schema = 'public'
  AND event_object_table = 'bookings'
  AND trigger_name IN ('trigger_update_drop_discount', 'trigger_update_drop_discount_on_delete');

  IF v_trigger_count < 2 THEN
    RAISE EXCEPTION 'Critical triggers missing! Expected 2, found %', v_trigger_count;
  END IF;

  RAISE NOTICE 'Verification passed: % drop discount triggers active', v_trigger_count;
END $$;

-- Create a function to calculate available stock for a product
-- This considers the original stock minus active bookings
CREATE OR REPLACE FUNCTION get_product_available_stock(product_id_param UUID)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_stock INTEGER;
  v_active_bookings INTEGER;
  v_available_stock INTEGER;
BEGIN
  -- Get the current stock from products table
  SELECT stock INTO v_stock
  FROM products
  WHERE id = product_id_param;

  -- If product doesn't exist, return 0
  IF v_stock IS NULL THEN
    RETURN 0;
  END IF;

  -- Count active bookings for this product
  SELECT COUNT(*) INTO v_active_bookings
  FROM bookings
  WHERE product_id = product_id_param
    AND status IN ('active', 'confirmed');

  -- Calculate available stock
  -- Note: stock field is already decremented by bookings via trigger
  -- So we just return the current stock value
  v_available_stock := v_stock;

  -- Ensure it's not negative
  IF v_available_stock < 0 THEN
    v_available_stock := 0;
  END IF;

  RETURN v_available_stock;
END;
$$;

-- Create a view that shows products with their available stock
CREATE OR REPLACE VIEW products_with_available_stock AS
SELECT 
  p.*,
  p.stock as available_stock,
  COALESCE(
    (SELECT COUNT(*) 
     FROM bookings b 
     WHERE b.product_id = p.id 
       AND b.status IN ('active', 'confirmed')),
    0
  ) as active_bookings_count
FROM products p;

-- Grant access to the view
GRANT SELECT ON products_with_available_stock TO authenticated;
GRANT SELECT ON products_with_available_stock TO anon;

-- Create an index on bookings for faster counting
CREATE INDEX IF NOT EXISTS idx_bookings_product_status 
ON bookings(product_id, status) 
WHERE status IN ('active', 'confirmed');

-- Add a comment to explain the view
COMMENT ON VIEW products_with_available_stock IS 
'View that shows products with their available stock. The available_stock field represents the actual stock available for booking (original stock minus active bookings). The stock field in the products table is automatically managed by the manage_product_stock_on_booking trigger.';

-- Create a function to broadcast product availability changes
CREATE OR REPLACE FUNCTION broadcast_product_availability_change()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_available_stock INTEGER;
BEGIN
  -- Calculate available stock
  v_available_stock := get_product_available_stock(NEW.id);

  -- Log the availability change
  RAISE NOTICE 'Product % availability changed: stock=%, available=%', 
    NEW.id, NEW.stock, v_available_stock;

  RETURN NEW;
END;
$$;

-- Create trigger to broadcast availability changes when stock changes
DROP TRIGGER IF EXISTS trigger_broadcast_product_availability ON products;
CREATE TRIGGER trigger_broadcast_product_availability
  AFTER UPDATE OF stock ON products
  FOR EACH ROW
  WHEN (OLD.stock IS DISTINCT FROM NEW.stock)
  EXECUTE FUNCTION broadcast_product_availability_change();

