[{"function_name":"award_loyalty_points","definition":"CREATE OR REPLACE FUNCTION public.award_loyalty_points(p_user_id uuid, p_amount_spent numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_rating INTEGER;
  v_points_to_award INTEGER;
BEGIN
  SELECT rating_stars INTO v_rating
  FROM profiles
  WHERE user_id = p_user_id;

  IF v_rating = 5 THEN
