-- Fix all RLS policies that directly query profiles table
-- Replace them with is_admin() function calls to prevent recursion

-- Create helper function for pickup point role check
CREATE OR REPLACE FUNCTION public.is_pickup_point()
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 
    FROM public.profiles
    WHERE user_id = auth.uid()
      AND role = 'pickup_point'
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.is_pickup_point() TO authenticated;
GRANT EXECUTE ON FUNCTION public.is_pickup_point() TO anon;

-- Create helper function to get current user's pickup point ID
CREATE OR REPLACE FUNCTION public.get_user_pickup_point_id()
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
BEGIN
  RETURN (
    SELECT pickup_point_id
    FROM public.profiles
    WHERE user_id = auth.uid()
      AND role = 'pickup_point'
    LIMIT 1
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_user_pickup_point_id() TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_user_pickup_point_id() TO anon;

-- Fix activity_logs policies
DROP POLICY IF EXISTS "Admins can view all activity logs" ON activity_logs;
CREATE POLICY "Admins can view all activity logs"
ON activity_logs
FOR SELECT
TO public
USING (is_admin());

-- Fix bookings policies
DROP POLICY IF EXISTS "Pickup points can view bookings for their location" ON bookings;
CREATE POLICY "Pickup points can view bookings for their location"
ON bookings
FOR SELECT
TO public
USING (is_pickup_point() AND pickup_point_id = get_user_pickup_point_id());

-- Fix coupons policies
DROP POLICY IF EXISTS "Admins can manage coupons" ON coupons;
CREATE POLICY "Admins can manage coupons"
ON coupons
FOR ALL
TO public
USING (is_admin());

-- Fix data_requests policies
DROP POLICY IF EXISTS "Admins can manage all data requests" ON data_requests;
CREATE POLICY "Admins can manage all data requests"
ON data_requests
FOR ALL
TO public
USING (is_admin());

-- Fix legal_documents policies
DROP POLICY IF EXISTS "Admins can manage legal documents" ON legal_documents;
CREATE POLICY "Admins can manage legal documents"
ON legal_documents
FOR ALL
TO public
USING (is_admin());

-- Fix orders policies
DROP POLICY IF EXISTS "Pickup points can view orders for their location" ON orders;
CREATE POLICY "Pickup points can view orders for their location"
ON orders
FOR SELECT
TO public
USING (is_pickup_point() AND pickup_point_id = get_user_pickup_point_id());

DROP POLICY IF EXISTS "Pickup points can update orders for their location" ON orders;
CREATE POLICY "Pickup points can update orders for their location"
ON orders
FOR UPDATE
TO public
USING (is_pickup_point() AND pickup_point_id = get_user_pickup_point_id());

-- Fix pickup_points policies
DROP POLICY IF EXISTS "Pickup point managers can update their own point" ON pickup_points;
CREATE POLICY "Pickup point managers can update their own point"
ON pickup_points
FOR UPDATE
TO public
USING (is_pickup_point() AND id = get_user_pickup_point_id());

DROP POLICY IF EXISTS "Users can view their own pending pickup points" ON pickup_points;
CREATE POLICY "Users can view their own pending pickup points"
ON pickup_points
FOR SELECT
TO public
USING (status = 'pending_approval' AND id = get_user_pickup_point_id());

-- Fix user_activity_log policies
DROP POLICY IF EXISTS "Admins can view all activity" ON user_activity_log;
CREATE POLICY "Admins can view all activity"
ON user_activity_log
FOR SELECT
TO public
USING (is_admin());

