USING (is_admin());

-- Add comments
COMMENT ON FUNCTION public.is_pickup_point() IS 
'Checks if the current user has pickup_point role. Uses SECURITY DEFINER to bypass RLS and prevent infinite recursion.';

COMMENT ON FUNCTION public.get_user_pickup_point_id() IS 
