-- Test querying various tables to ensure no recursion
SELECT COUNT(*) as profiles_count FROM profiles;
SELECT COUNT(*) as app_settings_count FROM app_settings;
SELECT COUNT(*) as activity_logs_count FROM activity_logs;
SELECT COUNT(*) as bookings_count FROM bookings;

