SELECT public.get_user_pickup_point_id() as pickup_point_id;

-- Drop existing helper functions
DROP FUNCTION IF EXISTS is_admin() CASCADE;
DROP FUNCTION IF EXISTS is_pickup_point() CASCADE;
DROP FUNCTION IF EXISTS get_user_pickup_point_id() CASCADE;

-- Create optimized SQL-based helper functions with STABLE and SECURITY DEFINER
-- These functions will be cached per transaction and bypass RLS

-- Function to check if current user is admin
CREATE OR REPLACE FUNCTION is_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles
    WHERE user_id = auth.uid()
      AND role = 'admin'
  );
$$;

-- Function to check if current user is pickup point
CREATE OR REPLACE FUNCTION is_pickup_point()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles
    WHERE user_id = auth.uid()
      AND role = 'pickup_point'
  );
$$;

-- Function to get pickup point ID for current user
CREATE OR REPLACE FUNCTION get_user_pickup_point_id()
RETURNS uuid
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT pickup_point_id
  FROM public.profiles
  WHERE user_id = auth.uid()
    AND role = 'pickup_point'
  LIMIT 1;
$$;

-- Drop all existing RLS policies on profiles table
DROP POLICY IF EXISTS "Users can view their own profile" ON profiles;
DROP POLICY IF EXISTS "Users can update their own profile" ON profiles;
DROP POLICY IF EXISTS "Admins can view all profiles" ON profiles;
DROP POLICY IF EXISTS "Admins can update all profiles" ON profiles;
DROP POLICY IF EXISTS "Admins can delete profiles" ON profiles;
DROP POLICY IF EXISTS "Users, system, and admins can insert profiles" ON profiles;
DROP POLICY IF EXISTS "Pickup points can view customer profiles for their orders" ON profiles;

-- Create new simplified RLS policies that avoid recursion
-- These policies use direct auth.uid() checks where possible

-- Allow users to view their own profile (no function call needed)
CREATE POLICY "Users can view their own profile"
ON profiles FOR SELECT
TO public
USING (user_id = auth.uid());

-- Allow users to update their own profile (no function call needed)
CREATE POLICY "Users can update their own profile"
ON profiles FOR UPDATE
TO public
USING (user_id = auth.uid())
WITH CHECK (user_id = auth.uid());

-- Allow admins to view all profiles
-- This is safe because is_admin() uses SECURITY DEFINER and STABLE
CREATE POLICY "Admins can view all profiles"
ON profiles FOR SELECT
TO public
USING (is_admin());

-- Allow admins to update all profiles
CREATE POLICY "Admins can update all profiles"
ON profiles FOR UPDATE
TO public
USING (is_admin());

-- Allow admins to delete profiles
CREATE POLICY "Admins can delete profiles"
ON profiles FOR DELETE
TO public
USING (is_admin());

-- Allow profile creation during signup (system) and by admins
-- For new user signup, auth.uid() will match user_id
-- For admin creation, is_admin() will be true
CREATE POLICY "Allow profile creation"
ON profiles FOR INSERT
TO public
WITH CHECK (
  user_id = auth.uid() OR is_admin()
);

-- Allow pickup points to view customer profiles for their orders
-- This policy is more complex but doesn't cause recursion because it doesn't call helper functions
CREATE POLICY "Pickup points can view customer profiles"
ON profiles FOR SELECT
TO public
USING (
  EXISTS (
    SELECT 1
    FROM order_items oi
    JOIN orders o ON o.id = oi.order_id
    WHERE oi.user_id = profiles.user_id
      AND o.pickup_point_id = (
        SELECT pickup_point_id
        FROM profiles p2
        WHERE p2.user_id = auth.uid()
          AND p2.role = 'pickup_point'
        LIMIT 1
      )
  )
);

-- Update app_settings policies to use the new helper functions
-- Drop existing policies
DROP POLICY IF EXISTS "Admins can select app settings" ON app_settings;
DROP POLICY IF EXISTS "Admins can insert app settings" ON app_settings;
DROP POLICY IF EXISTS "Admins can update app settings" ON app_settings;
DROP POLICY IF EXISTS "Admins can delete app settings" ON app_settings;
DROP POLICY IF EXISTS "Anonymous users can read app settings" ON app_settings;
DROP POLICY IF EXISTS "Authenticated users can read app settings" ON app_settings;

-- Recreate app_settings policies
CREATE POLICY "Anyone can read app settings"
ON app_settings FOR SELECT
TO public
USING (true);

CREATE POLICY "Admins can insert app settings"
ON app_settings FOR INSERT
TO public
WITH CHECK (is_admin());

CREATE POLICY "Admins can update app settings"
ON app_settings FOR UPDATE
TO public
USING (is_admin())
WITH CHECK (is_admin());

CREATE POLICY "Admins can delete app settings"
ON app_settings FOR DELETE
TO public
USING (is_admin());

