GRANT EXECUTE ON FUNCTION is_admin() TO public;
GRANT EXECUTE ON FUNCTION is_pickup_point() TO public;
GRANT EXECUTE ON FUNCTION get_user_pickup_point_id() TO public;

-- Add helpful comments
COMMENT ON FUNCTION is_admin() IS 'Check if current user has admin role. Uses SECURITY DEFINER to bypass RLS and STABLE for caching.';
COMMENT ON FUNCTION is_pickup_point() IS 'Check if current user has pickup_point role. Uses SECURITY DEFINER to bypass RLS and STABLE for caching.';
COMMENT ON FUNCTION get_user_pickup_point_id() IS 'Get pickup point ID for current user. Uses SECURITY DEFINER to bypass RLS and STABLE for caching.';

