-- Update handle_new_user to sync metadata immediately
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth'
AS $$
DECLARE
  v_pickup_point_id uuid;
  v_role text;
  v_error_message text;
BEGIN
  -- Log the start of profile creation
  RAISE LOG 'Starting profile creation for user %', new.id;

  -- Convert pickup_point_id from text to uuid, handling null values
  BEGIN
    v_pickup_point_id := (new.raw_user_meta_data->>'pickup_point_id')::uuid;
  EXCEPTION WHEN others THEN
    v_pickup_point_id := null;
    RAISE LOG 'Could not parse pickup_point_id for user %: %', new.id, SQLERRM;
  END;

  -- Get role from metadata, default to consumer
  v_role := COALESCE(new.raw_user_meta_data->>'role', 'consumer');

  -- Insert profile with data from user metadata
  BEGIN
    INSERT INTO public.profiles (user_id, email, full_name, phone, role, pickup_point_id)
    VALUES (
      new.id,
      new.email,
      COALESCE(new.raw_user_meta_data->>'full_name', ''),
      new.raw_user_meta_data->>'phone',
      v_role,
      v_pickup_point_id
    );

    RAISE LOG 'Successfully created profile for user %', new.id;

    -- Immediately sync metadata to auth.users.raw_app_meta_data
    -- This ensures the JWT will have the correct role information
    UPDATE auth.users
    SET raw_app_meta_data = 
      COALESCE(raw_app_meta_data, '{}'::jsonb) || 
      jsonb_build_object(
        'role', v_role,
        'pickup_point_id', v_pickup_point_id
      )
    WHERE id = new.id;

    RAISE LOG 'Successfully synced metadata for user %', new.id;

  EXCEPTION WHEN foreign_key_violation THEN
    -- This should not happen, but log it if it does
    v_error_message := SQLERRM;
    RAISE WARNING 'Foreign key violation creating profile for user %: %. This may indicate a timing issue.', new.id, v_error_message;

    -- Don't fail the user creation, but log the error
    RETURN new;

  WHEN unique_violation THEN
    -- Profile already exists, this is OK
    RAISE LOG 'Profile already exists for user %, skipping creation', new.id;
    RETURN new;

  WHEN others THEN
    -- Log any other error but don't fail the user creation
    v_error_message := SQLERRM;
    RAISE WARNING 'Error creating profile for user %: %', new.id, v_error_message;
    RETURN new;
  END;

  RETURN new;
END;
$$;

-- Test the helper functions to ensure they work without recursion
-- This should return false since we're not authenticated
SELECT 
    public.is_admin() as is_admin_result,
    public.is_pickup_point() as is_pickup_point_result,
    public.get_user_pickup_point_id() as pickup_point_id_result;

-- Clean up duplicate policies and ensure consistency

-- Drop duplicate app_settings policies
DROP POLICY IF EXISTS "Anyone can read app settings" ON public.app_settings;
DROP POLICY IF EXISTS "Everyone can view app settings" ON public.app_settings;
DROP POLICY IF EXISTS "Admins can manage app settings" ON public.app_settings;

-- Recreate with consistent naming
CREATE POLICY "app_settings_select_all"
ON public.app_settings
FOR SELECT
TO public
USING (true);

CREATE POLICY "app_settings_admin_all"
ON public.app_settings
FOR ALL
TO public
USING (
  COALESCE(
    (auth.jwt() -> 'app_metadata' ->> 'role')::text = 'admin',
    false
  )
);

-- Ensure all other tables use JWT-based checks consistently
-- Update any remaining policies that might use the old helper functions

-- Check and update pickup_points policies
DROP POLICY IF EXISTS "Admins can manage pickup points" ON public.pickup_points;
DROP POLICY IF EXISTS "Everyone can view active pickup points" ON public.pickup_points;
DROP POLICY IF EXISTS "Pickup points can view their own data" ON public.pickup_points;

CREATE POLICY "pickup_points_select_active"
ON public.pickup_points
FOR SELECT
TO public
USING (
  status = 'active' 
  OR 
  COALESCE(
    (auth.jwt() -> 'app_metadata' ->> 'role')::text = 'admin',
    false
  )
  OR
  (
    COALESCE(
      (auth.jwt() -> 'app_metadata' ->> 'role')::text = 'pickup_point',
      false
    )
    AND id = COALESCE(
      (auth.jwt() -> 'app_metadata' ->> 'pickup_point_id')::uuid,
      NULL
    )
  )
);

CREATE POLICY "pickup_points_admin_all"
ON public.pickup_points
FOR ALL
TO public
USING (
  COALESCE(
    (auth.jwt() -> 'app_metadata' ->> 'role')::text = 'admin',
    false
  )
);

-- Update notifications policies
DROP POLICY IF EXISTS "Users can view their own notifications" ON public.notifications;
DROP POLICY IF EXISTS "Admins can manage all notifications" ON public.notifications;

CREATE POLICY "notifications_select_own"
ON public.notifications
FOR SELECT
TO public
USING (
  user_id = auth.uid()
  OR
  COALESCE(
    (auth.jwt() -> 'app_metadata' ->> 'role')::text = 'admin',
    false
  )
);

CREATE POLICY "notifications_update_own"
ON public.notifications
FOR UPDATE
TO public
USING (user_id = auth.uid())
WITH CHECK (user_id = auth.uid());

CREATE POLICY "notifications_admin_all"
ON public.notifications
FOR ALL
TO public
USING (
  COALESCE(
    (auth.jwt() -> 'app_metadata' ->> 'role')::text = 'admin',
    false
  )
);

-- Add comment explaining the approach
COMMENT ON TABLE public.profiles IS 
'User profiles table. RLS policies use auth.jwt() app_metadata to avoid infinite recursion. Role and pickup_point_id are synced to JWT via triggers.';

