-- ============================================================================
-- COMPLETE FIX FOR INFINITE RECURSION IN RLS POLICIES
-- ============================================================================
-- This migration completely resolves the infinite recursion error by:
-- 1. Dropping all existing problematic policies
-- 2. Creating simple, non-recursive policies that only use auth.uid()
-- 3. Ensuring metadata is synced for all existing users
-- 4. Updating helper functions to be more robust
-- ============================================================================

-- Step 1: Drop all existing policies on profiles table
DROP POLICY IF EXISTS "Users can view their own profile" ON profiles;
DROP POLICY IF EXISTS "Users can update their own profile" ON profiles;
DROP POLICY IF EXISTS "Allow profile creation" ON profiles;
DROP POLICY IF EXISTS "Admins can view all profiles" ON profiles;
DROP POLICY IF EXISTS "Admins can update all profiles" ON profiles;
DROP POLICY IF EXISTS "Admins can delete profiles" ON profiles;
DROP POLICY IF EXISTS "Pickup points can view customer profiles" ON profiles;

-- Step 2: Create simple, non-recursive policies
-- These policies ONLY use auth.uid() and JWT metadata, never query profiles table

-- Allow users to view their own profile
CREATE POLICY "Users can view own profile"
ON profiles FOR SELECT
TO public
USING (user_id = auth.uid());

-- Allow users to update their own profile
CREATE POLICY "Users can update own profile"
ON profiles FOR UPDATE
TO public
USING (user_id = auth.uid())
WITH CHECK (user_id = auth.uid());

-- Allow profile creation during signup (by the user themselves or by admin)
CREATE POLICY "Allow profile creation"
ON profiles FOR INSERT
TO public
WITH CHECK (
  user_id = auth.uid() 
  OR 
  COALESCE((auth.jwt() -> 'app_metadata' ->> 'role')::text, '') = 'admin'
);

-- Allow admins to view all profiles
CREATE POLICY "Admins can view all profiles"
ON profiles FOR SELECT
TO public
USING (
  COALESCE((auth.jwt() -> 'app_metadata' ->> 'role')::text, '') = 'admin'
);

-- Allow admins to update all profiles
CREATE POLICY "Admins can update all profiles"
ON profiles FOR UPDATE
TO public
USING (
  COALESCE((auth.jwt() -> 'app_metadata' ->> 'role')::text, '') = 'admin'
);

-- Allow admins to delete profiles
CREATE POLICY "Admins can delete profiles"
ON profiles FOR DELETE
TO public
USING (
  COALESCE((auth.jwt() -> 'app_metadata' ->> 'role')::text, '') = 'admin'
);

-- Allow pickup points to view profiles of users who have orders at their location
-- This is the only complex policy, but it doesn't query profiles table
CREATE POLICY "Pickup points can view customer profiles"
ON profiles FOR SELECT
TO public
USING (
  COALESCE((auth.jwt() -> 'app_metadata' ->> 'role')::text, '') = 'pickup_point'
  AND
  EXISTS (
    SELECT 1
    FROM order_items oi
    JOIN orders o ON o.id = oi.order_id
    WHERE oi.user_id = profiles.user_id
    AND o.pickup_point_id = COALESCE((auth.jwt() -> 'app_metadata' ->> 'pickup_point_id')::uuid, NULL)
  )
);

-- Step 3: Update helper functions to be more robust
-- These functions are already correct, but let's ensure they have proper error handling

CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT COALESCE(
    (auth.jwt() -> 'app_metadata' ->> 'role')::text = 'admin',
    false
  );
$$;

CREATE OR REPLACE FUNCTION public.is_pickup_point()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT COALESCE(
    (auth.jwt() -> 'app_metadata' ->> 'role')::text = 'pickup_point',
    false
  );
$$;

CREATE OR REPLACE FUNCTION public.get_user_pickup_point_id()
RETURNS uuid
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT COALESCE(
    (auth.jwt() -> 'app_metadata' ->> 'pickup_point_id')::uuid,
    NULL
  );
$$;

-- Step 4: Ensure sync_user_metadata function is correct
CREATE OR REPLACE FUNCTION public.sync_user_metadata()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  -- Update auth.users raw_app_meta_data with role and pickup_point_id
  -- This ensures the JWT will have the correct information on next refresh
  UPDATE auth.users
  SET raw_app_meta_data = 
    COALESCE(raw_app_meta_data, '{}'::jsonb) || 
    jsonb_build_object(
      'role', NEW.role,
      'pickup_point_id', NEW.pickup_point_id
    )
  WHERE id = NEW.user_id;

  RETURN NEW;
END;
$$;

-- Ensure the trigger exists
DROP TRIGGER IF EXISTS sync_user_metadata_trigger ON profiles;
CREATE TRIGGER sync_user_metadata_trigger
AFTER INSERT OR UPDATE OF role, pickup_point_id ON profiles
FOR EACH ROW
EXECUTE FUNCTION sync_user_metadata();

-- Step 5: Sync metadata for ALL existing users
-- This is critical - it ensures all existing users have their metadata in JWT
DO $$
DECLARE
  profile_record RECORD;
  updated_count INTEGER := 0;
BEGIN
  RAISE NOTICE 'Starting metadata sync for all existing users...';

  FOR profile_record IN 
    SELECT user_id, role, pickup_point_id 
    FROM profiles
  LOOP
    BEGIN
      UPDATE auth.users
      SET raw_app_meta_data = 
        COALESCE(raw_app_meta_data, '{}'::jsonb) || 
        jsonb_build_object(
          'role', profile_record.role,
          'pickup_point_id', profile_record.pickup_point_id
        )
      WHERE id = profile_record.user_id;

      updated_count := updated_count + 1;
    EXCEPTION WHEN others THEN
      RAISE WARNING 'Failed to sync metadata for user %: %', profile_record.user_id, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE 'Metadata sync complete. Updated % users.', updated_count;
END;
$$;

-- Step 6: Update handle_new_user to set metadata IMMEDIATELY
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_pickup_point_id uuid;
  v_role text;
  v_error_message text;
BEGIN
  -- Log the start of profile creation
  RAISE LOG 'Starting profile creation for user %', new.id;

  -- Convert pickup_point_id from text to uuid, handling null values
  BEGIN
    v_pickup_point_id := (new.raw_user_meta_data->>'pickup_point_id')::uuid;
  EXCEPTION WHEN others THEN
    v_pickup_point_id := null;
    RAISE LOG 'Could not parse pickup_point_id for user %: %', new.id, SQLERRM;
  END;

  -- Get role from metadata, default to consumer
  v_role := COALESCE(new.raw_user_meta_data->>'role', 'consumer');

  -- FIRST: Set the app_metadata in auth.users BEFORE creating profile
  -- This ensures the JWT will have the correct role information immediately
  BEGIN
    UPDATE auth.users
    SET raw_app_meta_data = 
      COALESCE(raw_app_meta_data, '{}'::jsonb) || 
      jsonb_build_object(
        'role', v_role,
        'pickup_point_id', v_pickup_point_id
      )
    WHERE id = new.id;

    RAISE LOG 'Successfully set app_metadata for user %', new.id;
  EXCEPTION WHEN others THEN
    v_error_message := SQLERRM;
    RAISE WARNING 'Error setting app_metadata for user %: %', new.id, v_error_message;
  END;

  -- THEN: Insert profile with data from user metadata
  BEGIN
    INSERT INTO public.profiles (user_id, email, full_name, phone, role, pickup_point_id)
    VALUES (
      new.id,
      new.email,
      COALESCE(new.raw_user_meta_data->>'full_name', ''),
      new.raw_user_meta_data->>'phone',
      v_role,
      v_pickup_point_id
    );

    RAISE LOG 'Successfully created profile for user %', new.id;

  EXCEPTION WHEN foreign_key_violation THEN
    -- This should not happen, but log it if it does
    v_error_message := SQLERRM;
    RAISE WARNING 'Foreign key violation creating profile for user %: %. This may indicate a timing issue.', new.id, v_error_message;

    -- Don't fail the user creation, but log the error
    RETURN new;

  WHEN unique_violation THEN
    -- Profile already exists, this is OK
    RAISE LOG 'Profile already exists for user %, skipping creation', new.id;
    RETURN new;

  WHEN others THEN
    -- Log any other error but don't fail the user creation
    v_error_message := SQLERRM;
    RAISE WARNING 'Error creating profile for user %: %', new.id, v_error_message;
    RETURN new;
  END;

  RETURN new;
END;
$$;

-- Step 7: Grant necessary permissions
GRANT USAGE ON SCHEMA public TO anon, authenticated;
GRANT SELECT ON profiles TO anon, authenticated;
GRANT INSERT, UPDATE ON profiles TO authenticated;
GRANT DELETE ON profiles TO authenticated;

-- Step 8: Add helpful comments
COMMENT ON POLICY "Users can view own profile" ON profiles IS 
  'Allows users to view their own profile using auth.uid()';
COMMENT ON POLICY "Admins can view all profiles" ON profiles IS 
  'Allows admins to view all profiles by checking JWT app_metadata role';
COMMENT ON POLICY "Pickup points can view customer profiles" ON profiles IS 
  'Allows pickup points to view profiles of users with orders at their location';

-- Final verification
DO $$
BEGIN
  RAISE NOTICE '============================================================================';
  RAISE NOTICE 'MIGRATION COMPLETE';
  RAISE NOTICE '============================================================================';
  RAISE NOTICE 'All RLS policies have been recreated without recursion';
  RAISE NOTICE 'All existing users have had their metadata synced';
  RAISE NOTICE 'New users will have metadata set immediately upon creation';
  RAISE NOTICE '============================================================================';
END;
$$;

