-- Add notification function for order status updates
CREATE OR REPLACE FUNCTION notify_user_order_status(
  p_user_id UUID,
  p_order_number TEXT,
  p_product_name TEXT,
  p_status TEXT
) RETURNS VOID AS $$
DECLARE
  v_title TEXT;
  v_message TEXT;
  v_type TEXT;
BEGIN
  -- Determine notification content based on status
  CASE p_status
    WHEN 'ready_for_pickup' THEN
      v_title := 'Ordine Pronto per il Ritiro';
      v_message := 'Il tuo ordine ' || p_order_number || ' è arrivato ed è pronto per il ritiro presso il punto di ritiro. Ricorda di portare un documento d''identità.';
      v_type := 'order_ready';
    WHEN 'picked_up' THEN
      v_title := 'Articolo Consegnato';
      v_message := 'L''articolo "' || p_product_name || '" dell''ordine ' || p_order_number || ' è stato consegnato con successo. Grazie per aver utilizzato il nostro servizio!';
      v_type := 'general';
    WHEN 'returned_to_sender' THEN
      v_title := 'Articolo Rispedito al Fornitore';
      v_message := 'L''articolo "' || p_product_name || '" dell''ordine ' || p_order_number || ' non è stato ritirato entro i termini e verrà rispedito al fornitore. Il tuo rating è stato aggiornato.';
      v_type := 'general';
    ELSE
      v_title := 'Aggiornamento Ordine';
      v_message := 'Il tuo ordine ' || p_order_number || ' è stato aggiornato.';
      v_type := 'general';
  END CASE;

  -- Insert notification
  INSERT INTO notifications (
    user_id,
    title,
    message,
    type,
    related_type,
    read,
    created_at
  ) VALUES (
    p_user_id,
    v_title,
    v_message,
    v_type,
    'order',
    false,
    NOW()
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to update user rating when order is returned
CREATE OR REPLACE FUNCTION handle_order_return(
  p_user_id UUID,
  p_order_item_id UUID
) RETURNS VOID AS $$
DECLARE
  v_orders_returned INT;
  v_new_rating INT;
BEGIN
  -- Increment orders_returned counter
  UPDATE profiles
  SET 
    orders_returned = COALESCE(orders_returned, 0) + 1,
    updated_at = NOW()
  WHERE user_id = p_user_id
  RETURNING orders_returned INTO v_orders_returned;

  -- Calculate new rating (5 stars - 1 star per 5 returns, minimum 1 star)
  v_new_rating := GREATEST(1, 5 - (v_orders_returned / 5));

  -- Update rating
  UPDATE profiles
  SET 
    rating_stars = v_new_rating,
    updated_at = NOW()
  WHERE user_id = p_user_id;

  -- Check if user should be blocked (5 or more returns)
  IF v_orders_returned >= 5 THEN
    UPDATE profiles
    SET 
      account_blocked = true,
      blocked_at = NOW(),
      blocked_reason = 'Account bloccato per 5 o più ordini non ritirati',
      updated_at = NOW()
    WHERE user_id = p_user_id;

    -- Send notification about account block
    INSERT INTO notifications (
      user_id,
      title,
      message,
      type,
      read,
      created_at
    ) VALUES (
      p_user_id,
      'Account Bloccato',
      'Il tuo account è stato bloccato a causa di 5 o più ordini non ritirati. Contatta il supporto per maggiori informazioni.',
      'general',
      false,
      NOW()
    );
  END IF;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to update user rating when order is picked up
CREATE OR REPLACE FUNCTION handle_order_pickup(
  p_user_id UUID
) RETURNS VOID AS $$
DECLARE
  v_orders_picked_up INT;
  v_orders_returned INT;
  v_new_rating INT;
BEGIN
  -- Increment orders_picked_up counter
  UPDATE profiles
  SET 
    orders_picked_up = COALESCE(orders_picked_up, 0) + 1,
    updated_at = NOW()
  WHERE user_id = p_user_id
  RETURNING orders_picked_up, COALESCE(orders_returned, 0) INTO v_orders_picked_up, v_orders_returned;

  -- Calculate new rating based on pickup/return ratio
  -- Base rating is 5, subtract 1 star for every 5 returns
  v_new_rating := GREATEST(1, 5 - (v_orders_returned / 5));

  -- Update rating
  UPDATE profiles
  SET 
    rating_stars = v_new_rating,
    updated_at = NOW()
  WHERE user_id = p_user_id;

  -- Award loyalty points (10 points per pickup)
  UPDATE profiles
  SET 
    loyalty_points = COALESCE(loyalty_points, 0) + 10,
    updated_at = NOW()
  WHERE user_id = p_user_id;

  -- Log activity
  INSERT INTO user_activity_log (
    user_id,
    activity_type,
    activity_data,
    points_earned,
    created_at
  ) VALUES (
    p_user_id,
    'order_pickup',
    jsonb_build_object('orders_picked_up', v_orders_picked_up),
    10,
    NOW()
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Grant execute permissions
GRANT EXECUTE ON FUNCTION notify_user_order_status(UUID, TEXT, TEXT, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION handle_order_return(UUID, UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION handle_order_pickup(UUID) TO authenticated;

-- Create index on order_items for faster queries
CREATE INDEX IF NOT EXISTS idx_order_items_pickup_status ON order_items(pickup_status);
CREATE INDEX IF NOT EXISTS idx_order_items_user_id ON order_items(user_id);
CREATE INDEX IF NOT EXISTS idx_order_items_order_id ON order_items(order_id);

-- Create index on orders for pickup point queries
CREATE INDEX IF NOT EXISTS idx_orders_pickup_point_id ON orders(pickup_point_id);
CREATE INDEX IF NOT EXISTS idx_orders_status ON orders(status);
CREATE INDEX IF NOT EXISTS idx_orders_drop_id ON orders(drop_id);

-- Create index on notifications for faster user queries
CREATE INDEX IF NOT EXISTS idx_notifications_user_id ON notifications(user_id);
CREATE INDEX IF NOT EXISTS idx_notifications_read ON notifications(read);

-- Create index on profiles for rating queries
CREATE INDEX IF NOT EXISTS idx_profiles_account_blocked ON profiles(account_blocked);
CREATE INDEX IF NOT EXISTS idx_profiles_rating_stars ON profiles(rating_stars);

COMMENT ON FUNCTION notify_user_order_status IS 'Sends notification to user about order status changes';
COMMENT ON FUNCTION handle_order_return IS 'Handles order return logic including rating update and account blocking';
COMMENT ON FUNCTION handle_order_pickup IS 'Handles order pickup logic including rating update and loyalty points';

-- Fix RLS policies for notification_flows table
-- The issue is that the INSERT policy checks auth.jwt() but the created_by field is not being set
-- We need to update the policy to allow admins to insert without requiring created_by

-- Drop existing policies
DROP POLICY IF EXISTS "Admins can create notification flows" ON notification_flows;
DROP POLICY IF EXISTS "Admins can view all notification flows" ON notification_flows;
DROP POLICY IF EXISTS "Admins can update notification flows" ON notification_flows;
DROP POLICY IF EXISTS "Admins can delete notification flows" ON notification_flows;

-- Create new policies that properly check admin role from JWT app_metadata
CREATE POLICY "Admins can view all notification flows"
ON notification_flows
FOR SELECT
TO authenticated
USING (
  (auth.jwt() -> 'app_metadata' ->> 'role') = 'admin'
);

CREATE POLICY "Admins can create notification flows"
ON notification_flows
FOR INSERT
TO authenticated
WITH CHECK (
  (auth.jwt() -> 'app_metadata' ->> 'role') = 'admin'
);

CREATE POLICY "Admins can update notification flows"
ON notification_flows
FOR UPDATE
TO authenticated
USING (
  (auth.jwt() -> 'app_metadata' ->> 'role') = 'admin'
)
WITH CHECK (
  (auth.jwt() -> 'app_metadata' ->> 'role') = 'admin'
);

CREATE POLICY "Admins can delete notification flows"
ON notification_flows
FOR DELETE
TO authenticated
USING (
  (auth.jwt() -> 'app_metadata' ->> 'role') = 'admin'
);

-- Create wishlists table
CREATE TABLE IF NOT EXISTS wishlists (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  drop_id UUID REFERENCES drops(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(user_id, product_id)
);

-- Enable RLS
ALTER TABLE wishlists ENABLE ROW LEVEL SECURITY;

-- Create RLS policies
CREATE POLICY "Users can view their own wishlist items"
  ON wishlists FOR SELECT
  USING (auth.uid() = user_id);

CREATE POLICY "Users can add items to their wishlist"
  ON wishlists FOR INSERT
  WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can remove items from their wishlist"
  ON wishlists FOR DELETE
  USING (auth.uid() = user_id);

-- Create index for better performance
CREATE INDEX IF NOT EXISTS idx_wishlists_user_id ON wishlists(user_id);
CREATE INDEX IF NOT EXISTS idx_wishlists_product_id ON wishlists(product_id);

COMMENT ON TABLE wishlists IS 'User wishlist for saving favorite products';
COMMENT ON COLUMN wishlists.drop_id IS 'Optional reference to the drop where the product was found';

