-- Create product_variants table to store individual size/color combinations
CREATE TABLE IF NOT EXISTS product_variants (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  size TEXT,
  color TEXT,
  stock INTEGER NOT NULL DEFAULT 0 CHECK (stock >= 0),
  status TEXT DEFAULT 'active' CHECK (status IN ('active', 'inactive', 'sold_out')),
  created_at TIMESTAMPTZ DEFAULT now(),
  updated_at TIMESTAMPTZ DEFAULT now(),
  UNIQUE(product_id, size, color)
);

-- Enable RLS
ALTER TABLE product_variants ENABLE ROW LEVEL SECURITY;

-- RLS Policies for product_variants
CREATE POLICY "Anyone can view active product variants"
  ON product_variants FOR SELECT
  USING (status = 'active' AND stock > 0);

CREATE POLICY "Admins can manage product variants"
  ON product_variants FOR ALL
  USING (
    EXISTS (
      SELECT 1 FROM profiles
      WHERE profiles.user_id = auth.uid()
      AND profiles.role = 'admin'
    )
  );

CREATE POLICY "Suppliers can manage their product variants"
  ON product_variants FOR ALL
  USING (
    EXISTS (
      SELECT 1 FROM products
      JOIN profiles ON profiles.user_id = products.supplier_id
      WHERE products.id = product_variants.product_id
      AND profiles.user_id = auth.uid()
      AND profiles.role = 'supplier'
    )
  );

-- Add index for faster queries
CREATE INDEX idx_product_variants_product_id ON product_variants(product_id);
CREATE INDEX idx_product_variants_stock ON product_variants(stock) WHERE stock > 0;

-- Add trigger to update updated_at
CREATE OR REPLACE FUNCTION update_product_variants_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER update_product_variants_updated_at
  BEFORE UPDATE ON product_variants
  FOR EACH ROW
  EXECUTE FUNCTION update_product_variants_updated_at();

-- Update bookings table to reference variant
ALTER TABLE bookings ADD COLUMN IF NOT EXISTS variant_id UUID REFERENCES product_variants(id) ON DELETE SET NULL;

-- Add comment
COMMENT ON TABLE product_variants IS 'Stores individual product variants with specific size/color combinations and their stock levels';
COMMENT ON COLUMN product_variants.size IS 'Size of the variant (e.g., S, M, L, XL)';
COMMENT ON COLUMN product_variants.color IS 'Color of the variant (e.g., Red, Blue, Black)';
COMMENT ON COLUMN product_variants.stock IS 'Available stock for this specific variant';
COMMENT ON COLUMN bookings.variant_id IS 'Reference to the specific product variant booked (if applicable)';

-- Drop existing trigger and function
DROP TRIGGER IF EXISTS on_booking_created ON bookings;
DROP FUNCTION IF EXISTS handle_booking_created();

-- Create updated function to handle variant stock
CREATE OR REPLACE FUNCTION handle_booking_created()
RETURNS TRIGGER AS $$
DECLARE
  v_product RECORD;
  v_drop RECORD;
  v_new_value NUMERIC;
  v_new_discount NUMERIC;
  v_min_discount NUMERIC;
  v_max_discount NUMERIC;
  v_min_value NUMERIC;
  v_max_value NUMERIC;
  v_discount_range NUMERIC;
  v_value_range NUMERIC;
  v_value_progress NUMERIC;
BEGIN
  -- Get product details
  SELECT * INTO v_product FROM products WHERE id = NEW.product_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Product not found';
  END IF;

  -- Check if variant_id is provided
  IF NEW.variant_id IS NOT NULL THEN
    -- Decrement variant stock
    UPDATE product_variants
    SET stock = stock - 1
    WHERE id = NEW.variant_id AND stock > 0;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Variant not available or out of stock';
    END IF;

    -- Also update the product's total stock (sum of all variants)
    UPDATE products
    SET stock = (
      SELECT COALESCE(SUM(stock), 0)
      FROM product_variants
      WHERE product_id = NEW.product_id
    )
    WHERE id = NEW.product_id;
  ELSE
    -- Decrement product stock directly (no variants)
    UPDATE products
    SET stock = stock - 1
    WHERE id = NEW.product_id AND stock > 0;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Product not available or out of stock';
    END IF;
  END IF;

  -- Get drop details
  SELECT * INTO v_drop FROM drops WHERE id = NEW.drop_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Drop not found';
  END IF;

  -- Get supplier list details for discount calculation
  SELECT 
    min_discount,
    max_discount,
    min_reservation_value,
    max_reservation_value
  INTO 
    v_min_discount,
    v_max_discount,
    v_min_value,
    v_max_value
  FROM supplier_lists
  WHERE id = v_drop.supplier_list_id;

  -- Calculate new drop value
  v_new_value := COALESCE(v_drop.current_value, 0) + NEW.final_price;

  -- Calculate new discount based on value progress
  IF v_new_value <= v_min_value THEN
    v_new_discount := v_min_discount;
  ELSIF v_new_value >= v_max_value THEN
    v_new_discount := v_max_discount;
  ELSE
    v_value_range := v_max_value - v_min_value;
    v_discount_range := v_max_discount - v_min_discount;
    v_value_progress := (v_new_value - v_min_value) / v_value_range;
    v_new_discount := v_min_discount + (v_discount_range * v_value_progress);
  END IF;

  -- Update drop with new values
  UPDATE drops
  SET 
    current_value = v_new_value,
    current_discount = v_new_discount,
    updated_at = NOW()
  WHERE id = NEW.drop_id;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Create trigger
CREATE TRIGGER on_booking_created
  AFTER INSERT ON bookings
  FOR EACH ROW
  EXECUTE FUNCTION handle_booking_created();

-- Add comment
COMMENT ON FUNCTION handle_booking_created() IS 'Handles booking creation: decrements variant or product stock, updates drop value and discount';

-- Fix RLS policy for supplier_lists to allow admins to create lists for suppliers
DROP POLICY IF EXISTS "Suppliers can insert their own lists" ON supplier_lists;
DROP POLICY IF EXISTS "Admins can insert supplier lists" ON supplier_lists;

-- Allow suppliers to insert their own lists
CREATE POLICY "Suppliers can insert their own lists"
ON supplier_lists
FOR INSERT
WITH CHECK (
  (SELECT auth.uid()) = supplier_id
);

-- Allow admins to insert lists for any supplier
CREATE POLICY "Admins can insert supplier lists"
ON supplier_lists
FOR INSERT
WITH CHECK (
  COALESCE((auth.jwt() -> 'app_metadata' ->> 'role'), '') = 'admin'
);

-- Ensure product_variants table has proper indexes for performance
CREATE INDEX IF NOT EXISTS idx_product_variants_product_id ON product_variants(product_id);
CREATE INDEX IF NOT EXISTS idx_product_variants_stock ON product_variants(stock) WHERE stock > 0;
CREATE INDEX IF NOT EXISTS idx_products_sku ON products(sku) WHERE sku IS NOT NULL;

-- Add comment to clarify SKU usage
COMMENT ON COLUMN products.sku IS 'Stock Keeping Unit - Products with the same SKU are treated as variants of the same article. Variants are stored in product_variants table with specific size/color combinations.';

