-- Make email column nullable in profiles table to support phone-only authentication
ALTER TABLE public.profiles 
ALTER COLUMN email DROP NOT NULL;

-- Add a check constraint to ensure at least one of email or phone is present
ALTER TABLE public.profiles 
ADD CONSTRAINT email_or_phone_required 
CHECK (email IS NOT NULL OR phone IS NOT NULL);

-- Add comment explaining the change
COMMENT ON COLUMN public.profiles.email IS 'User email address - nullable to support phone-only authentication. Either email or phone must be present.';

