-- Update handle_new_user function to properly handle phone-only authentication
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_pickup_point_id uuid;
  v_role text;
  v_error_message text;
  v_phone text;
BEGIN
  -- Log the start of profile creation
  RAISE LOG 'Starting profile creation for user %', new.id;

  -- Convert pickup_point_id from text to uuid, handling null values
  BEGIN
    v_pickup_point_id := (new.raw_user_meta_data->>'pickup_point_id')::uuid;
  EXCEPTION WHEN others THEN
    v_pickup_point_id := null;
    RAISE LOG 'Could not parse pickup_point_id for user %: %', new.id, SQLERRM;
  END;

  -- Get role from metadata, default to consumer
  v_role := COALESCE(new.raw_user_meta_data->>'role', 'consumer');

  -- Get phone from auth.users.phone or metadata
  v_phone := COALESCE(new.phone, new.raw_user_meta_data->>'phone');

  -- FIRST: Set the app_metadata in auth.users BEFORE creating profile
  -- This ensures the JWT will have the correct role information immediately
  BEGIN
    UPDATE auth.users
    SET raw_app_meta_data = 
      COALESCE(raw_app_meta_data, '{}'::jsonb) || 
      jsonb_build_object(
        'role', v_role,
        'pickup_point_id', v_pickup_point_id
      )
    WHERE id = new.id;

    RAISE LOG 'Successfully set app_metadata for user %', new.id;
  EXCEPTION WHEN others THEN
    v_error_message := SQLERRM;
    RAISE WARNING 'Error setting app_metadata for user %: %', new.id, v_error_message;
  END;

  -- THEN: Insert profile with data from user metadata
  -- Email can be NULL for phone-only authentication
  BEGIN
    INSERT INTO public.profiles (user_id, email, full_name, phone, role, pickup_point_id)
    VALUES (
      new.id,
      new.email, -- Can be NULL for phone-only auth
      new.raw_user_meta_data->>'full_name',
      v_phone,
      v_role,
      v_pickup_point_id
    );

    RAISE LOG 'Successfully created profile for user % with email=% phone=%', new.id, new.email, v_phone;

  EXCEPTION WHEN foreign_key_violation THEN
    -- This should not happen, but log it if it does
    v_error_message := SQLERRM;
    RAISE WARNING 'Foreign key violation creating profile for user %: %. This may indicate a timing issue.', new.id, v_error_message;

    -- Don't fail the user creation, but log the error
    RETURN new;

  WHEN unique_violation THEN
    -- Profile already exists, this is OK
    RAISE LOG 'Profile already exists for user %, skipping creation', new.id;
    RETURN new;

  WHEN others THEN
    -- Log any other error but don't fail the user creation
    v_error_message := SQLERRM;
    RAISE WARNING 'Error creating profile for user %: %', new.id, v_error_message;
    RETURN new;
  END;

  RETURN new;
END;
$function$;

-- Update handle_phone_user_creation function to handle NULL email properly
CREATE OR REPLACE FUNCTION public.handle_phone_user_creation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  -- If user is created with phone, ensure profile is created with phone
  IF NEW.phone IS NOT NULL THEN
    INSERT INTO public.profiles (
      user_id,
      email,
      phone,
      full_name,
      role,
      pickup_point_id
    )
    VALUES (
      NEW.id,
      NEW.email, -- Can be NULL for phone-only auth
      NEW.phone,
      NEW.raw_user_meta_data->>'full_name',
      COALESCE(NEW.raw_user_meta_data->>'role', 'consumer'),
      (NEW.raw_user_meta_data->>'pickup_point_id')::uuid
    )
    ON CONFLICT (user_id) DO UPDATE SET
      phone = EXCLUDED.phone,
      email = COALESCE(EXCLUDED.email, profiles.email),
      full_name = COALESCE(EXCLUDED.full_name, profiles.full_name),
      updated_at = now();
  END IF;

  RETURN NEW;
END;
$function$;

