-- Create list_shares table to track when users share lists
CREATE TABLE IF NOT EXISTS list_shares (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  supplier_list_id UUID NOT NULL REFERENCES supplier_lists(id) ON DELETE CASCADE,
  pickup_point_id UUID NOT NULL REFERENCES pickup_points(id) ON DELETE CASCADE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Enable RLS
ALTER TABLE list_shares ENABLE ROW LEVEL SECURITY;

-- Create RLS policies
CREATE POLICY "Users can view their own shares"
  ON list_shares
  FOR SELECT
  USING (user_id = auth.uid());

CREATE POLICY "Users can create their own shares"
  ON list_shares
  FOR INSERT
  WITH CHECK (user_id = auth.uid());

-- Create index for performance
CREATE INDEX idx_list_shares_user_id ON list_shares(user_id);
CREATE INDEX idx_list_shares_supplier_list_id ON list_shares(supplier_list_id);
CREATE INDEX idx_list_shares_pickup_point_id ON list_shares(pickup_point_id);
CREATE INDEX idx_list_shares_created_at ON list_shares(created_at DESC);

-- Add comment
COMMENT ON TABLE list_shares IS 'Tracks when users share supplier lists with friends and family to increase drop activation chances';

